#include <iostream>
#include <list>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> source = {1, 2, 3, 4, 5};
    std::list<int> target;
    // Use std::front_inserter to insert elements at the front of the list
    std::copy(source.begin(), source.end(), std::front_inserter(target));
    // Output the list elements
    for (int n : target) {
        std::cout << n << ' ';
    }
    return 0;
}
